function shell(){const app=$('app');if(!app||app.hidden||$('adminSidebar'))return;app.classList.add('admin-layout');const side=document.createElement('aside');side.id='adminSidebar';side.innerHTML='<div class="side-brand">শায়লা আকরাম কেন্দ্রীয় জামে মসজিদ<br><small>শায়লা আকরাম কেন্দ্রীয় ফাউন্ডেশন</small><small>ADMIN CONTROL CENTER</small></div>';const existing=[...app.querySelectorAll(':scope>.panel')];legacyPanels.users=existing.find(x=>x.id==='staffManager');legacyPanels.userList=existing.find(x=>x.textContent.includes('ব্যবহারকারী ও দায়িত্ব'));legacyPanels.media=existing.find(x=>x.id==='mosqueMediaAdmin');legacyPanels.notices=existing.find(x=>x.textContent.includes('নোটিশ তৈরি ও প্রকাশ'));legacyPanels.content=existing.find(x=>x.textContent.includes('হোমপেজ কনটেন্ট ব্যবস্থাপনা'));legacyPanels.audit=existing.find(x=>x.textContent.includes('নিরাপত্তা ও অডিট লগ'));groups.forEach((g,i)=>{const d=document.createElement('details');d.open=i===0;const s=document.createElement('summary');s.textContent=i===4?'E · Accounts পরিচালনা':g;d.append(s);if(i===4&&profile.role!=='custom_admin'){const a=document.createElement('a');a.href='./accounts.html';a.textContent='Accounts Admin Panel খুলুন';d.append(a)}else{if(i===4&&profile.role==='custom_admin'&&modulePermissions.some(p=>/^m(6[2-9]|7[0-9]|8[0-5])$/.test(p.module_key)&&p.can_view)){const a=document.createElement('a');a.href='./accounts.html';a.textContent='Accounts Admin Panel খুলুন';d.append(a)}mods.filter(m=>m.g===i).forEach(m=>{if(!readable(m))return;const a=document.createElement('a');a.href='#admin='+m.key;a.dataset.key=m.key;a.textContent=m.n.toLocaleString('bn-BD')+'. '+m.name;d.append(a)})}side.append(d)});const foot=document.createElement('div');foot.className='side-foot';foot.textContent='ওয়েবসাইট ব্যবস্থাপনা · পৃথক Accounts Panel';side.append(foot);app.prepend(side);const ws=document.createElement('section');ws.id='adminWorkspace';side.after(ws);[...app.querySelectorAll(':scope>.panel')].forEach(x=>{x.hidden=true});app.querySelector(':scope>.grid')?.setAttribute('hidden','');app.querySelector(':scope>.top')?.setAttribute('hidden','');window.addEventListener('hashchange',render);render()}

